-- 0037 — Sourced industry benchmarks, activated (Pedro, 2026-10-16).
--
-- Pedro's direction: "not inventing numbers but do be flexible… research real
-- data that people/companies that use or have done similar things experience
-- x amount of returns or save x amount of time etc and use that even if we
-- personally don't have numbers directly tied to our platforms."
--
-- So this seeds 41 statistics on what businesses typically see after the kind
-- of change Rünna sells (answering enquiries fast, automation, dashboards,
-- online booking and reminders, faster sites, cart recovery, retention,
-- reviews, OTA dependence), each with its publisher and source URL, and
-- activates 4 earlier, first-hand-researched rows that were waiting for review.
-- The composer may cite only these; the send gate holds any other number.
--
-- How they were checked: three research passes on 2026-10-16 plus spot-checks.
-- The session's network policy blocked opening pages directly, so every figure
-- was confirmed against search excerpts from the publisher's OWN page, and a
-- sample (Gartner 67%, Nucleus $6.20, Science 40%, BMJ Open 25%, Baymard
-- 70.22%, BrightLocal 31%, Toast 65%) was re-confirmed independently. Dropped
-- on purpose: forecasts (Gartner's 2029 AI prediction), predictions (Thomson
-- Reuters' expected hours saved), "up to" ceilings and modeled potentials
-- (Google's up-to-20%, Baymard's 35.26%), one company's own results (Klarna),
-- and anything that couldn't be traced (Phorest's 46% after-hours bookings).
-- Vendor studies are kept and flagged is_vendor_sourced; every caveat says
-- what the figure does and doesn't measure.
--
-- Idempotent: a row is only inserted when (tenant, source_url, figure) is new.

update public.benchmarks
set is_active = true,
    verified_at = coalesce(verified_at, now()),
    caveat = coalesce(caveat, '') || ' Activated 2026-10-16 under Pedro''s instruction to use sourced industry data.',
    updated_at = now()
where is_active = false
  and figure in ('23%', '8.3%', 'twice', '78%')
  and publisher in (
    'Harvard Business Review (Oldroyd, McElheran, Elkington)',
    'Deloitte Digital + 55, commissioned by Google',
    'GlobalSpec + TREW Marketing + Elektor, State of Marketing to Engineers 2025',
    'Canadian Federation of Independent Business (CFIB)'
  );

-- Part 1 of 2
insert into public.benchmarks (
  tenant_id, statistic, figure, pain_codes, industry_scope, market,
  source_url, publisher, published_date, is_vendor_sourced, caveat,
  is_active, verified_at
)
select
  t.id, v.statistic, v.figure, v.pain_codes, v.industry_scope, v.market,
  v.source_url, v.publisher, v.published_date, v.is_vendor_sourced,
  v.caveat || ' ' || 'Source-checked by Claude on 2026-10-16 against search excerpts from the publisher''s own page (the page itself could not be opened: session network policy); activated under Pedro''s 2026-10-16 instruction to use sourced industry data. Review on /benchmarks.',
  true, now()
from public.tenants t
cross join (values
  ('Among companies that did reply to a web enquiry, the average first response took 42 hours (Harvard Business Review audit of 2,241 US companies).', '42 hours', array['manual_sales_process', 'competitor_pressure'], array['accounting firm', 'chartered accountant', 'despacho contable', 'law firm', 'despacho de abogados', 'agencia de seguros', 'manufacturer', 'manufacturing', 'distribution', 'distributor', 'wholesale', 'wholesale distributor', 'construction', 'software development', 'real estate agency', 'inmobiliaria'], null, 'https://hbr.org/2011/03/the-short-life-of-online-sales-leads', 'Harvard Business Review (Oldroyd, McElheran, Elkington)', date '2011-03-01', false, 'Landmark 2011 study, US companies only. Counts only companies that replied within 30 days. Co-author Elkington ran InsideSales.com (disclosed in the article).'),
  ('In a secret-shopper test of 433 companies, only 7% replied to an inbound enquiry within five minutes, and 55% had not replied at all after five business days.', '55%', array['manual_sales_process', 'competitor_pressure'], array['manufacturer', 'manufacturing', 'distribution', 'distributor', 'wholesale', 'wholesale distributor', 'construction', 'software development', 'accounting firm', 'chartered accountant', 'despacho contable', 'law firm', 'despacho de abogados', 'agencia de seguros'], null, 'https://blog.drift.com/lead-response-survey/', 'Drift (Lead Response Report)', date '2017-01-01', true, 'Vendor that sells chat tools; sample mostly US B2B and software companies.'),
  ('In a controlled experiment published in Science, professionals using an AI writing assistant finished writing tasks 40% faster, and the quality of their work rose 18%.', '40%', array['slow_production_cycles', 'manual_sales_process', 'no_content_velocity'], array['accounting firm', 'chartered accountant', 'despacho contable', 'law firm', 'despacho de abogados', 'agencia de seguros', 'real estate agency', 'inmobiliaria', 'manufacturer', 'manufacturing', 'distribution', 'distributor', 'wholesale', 'wholesale distributor', 'construction', 'software development'], 'GLOBAL', 'https://www.science.org/doi/10.1126/science.adh2586', 'Science (Noy & Zhang, MIT)', date '2023-07-13', false, 'Online experiment, 453 college-educated professionals, single task type, ChatGPT-3.5. A later real-world Copilot study found smaller effects. Say ''writing tasks'', not ''all work''.'),
  ('Over 40% of office workers spend at least a quarter of their work week on manual, repetitive tasks, with email, data collection and data entry taking the most time.', 'over 40%', array['manual_sales_process', 'slow_production_cycles'], array['accounting firm', 'chartered accountant', 'despacho contable', 'law firm', 'despacho de abogados', 'agencia de seguros', 'manufacturer', 'manufacturing', 'distribution', 'distributor', 'wholesale', 'wholesale distributor', 'construction', 'software development'], null, 'https://www.smartsheet.com/content-center/product-news/automation/workers-waste-quarter-work-week-manual-repetitive-tasks', 'Smartsheet (survey by Market Cube)', date '2017-01-01', true, 'Vendor survey of about 1,000 US information workers, 2017. The press release gives 42%.'),
  ('The average salesperson spends only 40% of their working time actually selling; the rest goes to admin and other tasks.', '40%', array['manual_sales_process'], array['manufacturer', 'manufacturing', 'distribution', 'distributor', 'wholesale', 'wholesale distributor', 'construction', 'software development', 'agencia de seguros'], null, 'https://www.salesforce.com/news/stories/state-of-sales-report-announcement-2026/', 'Salesforce (State of Sales, 7th edition)', date '2026-01-01', true, 'Vendor survey of 4,050 sales professionals worldwide, Aug–Sep 2025.'),
  ('Support agents given an AI assistant resolved 14% more customer issues per hour on average, and newer agents 34% more.', '14%', array['low_customer_retention', 'manual_sales_process'], array['manufacturer', 'manufacturing', 'distribution', 'distributor', 'wholesale', 'wholesale distributor', 'construction', 'software development', 'agencia de seguros', 'clínica'], null, 'https://www.nber.org/papers/w31161', 'NBER (Brynjolfsson, Li & Raymond)', date '2023-04-01', false, '5,179 agents at one company. The published QJE version reports 15%.'),
  ('In an average 8-hour work day, lawyers bill only 3.0 hours: a 38% utilization rate.', '38%', array['slow_production_cycles', 'manual_sales_process'], array['law firm', 'despacho de abogados'], null, 'https://www.clio.com/resources/legal-trends/benchmarks/', 'Clio (Legal Trends Report)', date '2025-01-01', true, 'Vendor data, US firms. Some Clio posts give 2.6–2.9 hours.'),
  ('Analytics and BI deployments returned an average of $6.20 for every dollar invested, across Nucleus Research''s ROI case studies.', '$6.20', array['competitor_pressure', 'manual_sales_process', 'slow_production_cycles'], array['manufacturer', 'manufacturing', 'distribution', 'distributor', 'wholesale', 'wholesale distributor', 'construction', 'software development', 'hospital', 'restaurant group', 'hotel chain'], null, 'https://nucleusresearch.com/research/single/analytics-technology-returns-6-20-for-every-dollar-spent/', 'Nucleus Research', date '2023-01-01', false, 'Based on Nucleus ROI case studies (often vendor-sponsored); about three years old. Earlier Nucleus figures ($13.01 in 2014, $9.01) differ.'),
  ('Companies that use customer analytics intensively are 23 times more likely to clearly outperform competitors in winning new customers.', '23 times', array['competitor_pressure', 'low_customer_retention'], array['manufacturer', 'manufacturing', 'distribution', 'distributor', 'wholesale', 'wholesale distributor', 'construction', 'software development', 'real estate agency', 'inmobiliaria', 'restaurant group', 'hotel chain'], null, 'https://www.mckinsey.com/capabilities/growth-marketing-and-sales/our-insights/five-facts-how-customer-analytics-boosts-corporate-performance', 'McKinsey & Company (DataMatics survey)', date '2014-07-01', false, '2013 survey data, correlational.'),
  ('Firms with advanced data and insights capabilities are 8.5 times more likely to report annual revenue growth of 20% or more than beginner firms.', '8.5 times', array['competitor_pressure'], array['manufacturer', 'manufacturing', 'distribution', 'distributor', 'wholesale', 'wholesale distributor', 'construction', 'software development'], null, 'https://www.forrester.com/blogs/is-your-b2b-organization-insights-driven/', 'Forrester', date '2023-01-01', false, 'Self-reported survey, correlational.'),
  ('Firms that make decisions based on data have 5-6% higher output and productivity than their other investments would predict.', '5-6%', array['competitor_pressure', 'slow_production_cycles'], array['manufacturer', 'manufacturing', 'distribution', 'distributor', 'wholesale distributor'], null, 'https://papers.ssrn.com/abstract=1819486', 'Brynjolfsson, Hitt & Kim (MIT / Wharton), Strength in Numbers', date '2011-04-01', false, 'Landmark academic study; 179 large US public firms.'),
  ('67% of B2B buyers say they prefer to buy without dealing with a sales rep.', '67%', array['outdated_website', 'manual_sales_process', 'competitor_pressure'], array['manufacturer', 'manufacturing', 'distribution', 'distributor', 'wholesale', 'wholesale distributor', 'construction', 'software development'], null, 'https://www.gartner.com/en/newsroom/press-releases/2026-03-09-gartner-sales-survey-finds-67-percent-of-b2b-buyers-prefer-a-rep-free-experience', 'Gartner', date '2026-03-09', false, 'Survey of 646 B2B buyers, Aug–Sep 2025. The 2025 edition reported 61%.'),
  ('71% of B2B companies now sell online in some form, and online sales account for 34% of their revenue.', '34 percent', array['outdated_website', 'competitor_pressure', 'manual_sales_process'], array['manufacturer', 'manufacturing', 'distribution', 'distributor', 'wholesale', 'wholesale distributor'], null, 'https://www.mckinsey.com/capabilities/growth-marketing-and-sales/our-insights/five-fundamental-truths-how-b2b-winners-keep-growing', 'McKinsey & Company (B2B Pulse Survey)', date '2024-01-01', false, 'Global survey of about 4,000 B2B decision makers.'),
  ('Across randomized studies, patients who got text reminders were 25% less likely to miss their appointment (no-show rate 15% vs 21%).', '25%', array['low_customer_retention', 'manual_sales_process'], array['hospital', 'clínica', 'spa', 'salón de belleza', 'estética', 'fitness studio'], null, 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5093388/', 'BMJ Open (Robotham et al., systematic review and meta-analysis)', date '2016-10-01', false, 'Healthcare appointments; 25% is relative (about 6 points absolute). Applying it to spas/salons is an extrapolation: say ''in clinics''.'),
  ('In a Cochrane review, appointment attendance was 67.8% with no reminder and 78.6% with a text-message reminder.', '78.6%', array['low_customer_retention'], array['hospital', 'clínica'], null, 'https://pubmed.ncbi.nlm.nih.gov/24310741/', 'Cochrane Database of Systematic Reviews (Gurol-Urganci et al.)', date '2013-12-01', false, 'Low-to-moderate quality evidence; text reminders worked about as well as phone calls at lower cost.'),
  ('89% of patients say being able to book appointments anytime online or by phone app is important.', '89%', array['outdated_website', 'low_customer_retention', 'manual_sales_process'], array['hospital', 'clínica'], null, 'https://www.experian.com/blogs/healthcare/the-state-of-patient-access-2024/', 'Experian Health (State of Patient Access 2024)', date '2024-01-01', true, 'Vendor survey of 1,000+ US patients, Feb 2024.'),
  ('Speeding up a mobile site by just 0.1 seconds lifted the share of visitors reaching the form-submission page on lead-generation sites by 21.6%.', '21.6%', array['outdated_website', 'poor_mobile_conversion', 'poor_paid_media_roas'], array['accounting firm', 'chartered accountant', 'despacho contable', 'law firm', 'despacho de abogados', 'agencia de seguros', 'manufacturer', 'manufacturing', 'distribution', 'distributor', 'wholesale', 'wholesale distributor', 'construction', 'software development', 'real estate agency', 'inmobiliaria', 'hospital', 'clínica'], 'GLOBAL', 'https://www.deloitte.com/ie/en/services/consulting/research/milliseconds-make-millions.html', 'Deloitte Digital, commissioned by Google (Milliseconds Make Millions)', date '2020-01-01', false, '37 EU/US brand sites over 30 days in 2019; correlational.'),
  ('Speeding up a mobile site by 0.1 seconds increased retail conversions by 8.4% and average order value by 9.2%.', '8.4%', array['poor_mobile_conversion', 'outdated_website'], array['online store', 'retail', 'hotel', 'hotel chain'], 'GLOBAL', 'https://www.deloitte.com/ie/en/services/consulting/research/milliseconds-make-millions.html', 'Deloitte Digital, commissioned by Google (Milliseconds Make Millions)', date '2020-01-01', false, 'Commissioned by Google; 37 brands in Europe and the US. Exact wording from a search summary.'),
  ('A B2B website that loads in 1 second converts 3 times better than one that loads in 5 seconds.', '3 times', array['outdated_website', 'poor_mobile_conversion', 'poor_paid_media_roas'], array['manufacturer', 'manufacturing', 'distribution', 'distributor', 'wholesale', 'wholesale distributor', 'construction', 'software development', 'accounting firm', 'chartered accountant', 'despacho contable', 'law firm', 'despacho de abogados', 'agencia de seguros'], null, 'https://portent.com/blog/analytics/research-site-speed-hurting-everyones-revenue.htm', 'Portent', date '2022-01-01', true, 'Correlational study by a web agency; 100M+ page views across 20 sites (14 B2B lead-gen).'),
  ('53% of mobile visits are likely to be abandoned if a page takes longer than three seconds to load.', '53%', array['poor_mobile_conversion', 'outdated_website'], array[]::text[], 'GLOBAL', 'https://support.google.com/adsense/answer/7450973?hl=en-GB', 'Google', date '2016-01-01', false, 'Based on 2016 Google data; dated.')
) as v(statistic, figure, pain_codes, industry_scope, market, source_url, publisher, published_date, is_vendor_sourced, caveat)
where not exists (
  select 1 from public.benchmarks b
  where b.tenant_id = t.id and b.source_url = v.source_url and b.figure = v.figure
);

-- Part 2 of 2
insert into public.benchmarks (
  tenant_id, statistic, figure, pain_codes, industry_scope, market,
  source_url, publisher, published_date, is_vendor_sourced, caveat,
  is_active, verified_at
)
select
  t.id, v.statistic, v.figure, v.pain_codes, v.industry_scope, v.market,
  v.source_url, v.publisher, v.published_date, v.is_vendor_sourced,
  v.caveat || ' ' || 'Source-checked by Claude on 2026-10-16 against search excerpts from the publisher''s own page (the page itself could not be opened: session network policy); activated under Pedro''s 2026-10-16 instruction to use sourced industry data. Review on /benchmarks.',
  true, now()
from public.tenants t
cross join (values
  ('In Stanford''s web-credibility research, a site''s visual design was the most-mentioned factor when people judged whether it was credible (46.1% of comments).', '46.1%', array['outdated_website', 'brand_inconsistency', 'no_proof'], array['accounting firm', 'chartered accountant', 'despacho contable', 'law firm', 'despacho de abogados', 'agencia de seguros', 'hospital', 'clínica', 'real estate agency', 'inmobiliaria', 'construction'], null, 'http://credibility.stanford.edu/pdf/How_Do_People_Evaluate_a_Web_Site''s_Credibility_v37.pdf', 'Stanford Persuasive Technology Lab (Fogg et al.)', date '2002-10-01', false, 'Landmark 2002 study; counts comments, not people.'),
  ('65% of diners go directly to the restaurant''s own website to make a reservation.', '65%', array['outdated_website', 'manual_sales_process'], array['restaurant', 'restaurant group'], null, 'https://pos.toasttab.com/blog/data/restaurant-wait-times-and-reservations-data', 'Toast', date '2025-07-16', true, 'Toast survey of 850 US adults, July 2025.'),
  ('About 44% of diners find a restaurant less appealing, or stop trying to book, when getting a reservation is too difficult.', '44%', array['outdated_website', 'competitor_pressure', 'manual_sales_process'], array['restaurant', 'restaurant group'], null, 'https://pos.toasttab.com/blog/data/restaurant-wait-times-and-reservations-data', 'Toast', date '2025-07-16', true, 'US consumer survey by a POS vendor.'),
  ('About 70% of online shopping carts are abandoned before purchase (70.22%, the average of 50 studies).', '70.22%', array['abandoned_cart_loss'], array['online store', 'retail'], 'GLOBAL', 'https://baymard.com/lists/cart-abandonment-rate', 'Baymard Institute', date '2025-09-22', false, 'Rolling average; other Baymard pages show 70.19% or 69%. Some abandonment is just browsing.'),
  ('Leaving out shoppers who were just browsing, 40% of people who abandon a checkout leave because the extra costs (shipping, tax, fees) were too high.', '40%', array['abandoned_cart_loss'], array['online store', 'retail'], null, 'https://baymard.com/learn/ux-statistics', 'Baymard Institute', date '2025-01-01', false, 'US shopper survey; other Baymard pages give other years'' figures.'),
  ('Abandoned-cart emails earn more per recipient than any other automated email, about $6.77 per person who receives one.', '$6.77', array['abandoned_cart_loss', 'low_email_performance'], array['online store', 'retail'], 'GLOBAL', 'https://www.klaviyo.com/blog/abandoned-cart-benchmarks', 'Klaviyo', date '2026-01-01', true, 'Platform data from 110,000+ Klaviyo customers, USD.'),
  ('Automated emails such as welcome and abandoned-cart messages were only 2% of emails sent but drove 30% of email revenue.', '30%', array['low_email_performance', 'abandoned_cart_loss', 'low_customer_retention'], array['online store', 'retail'], 'GLOBAL', 'https://www.omnisend.com/resources/reports/2026-ecommerce-marketing-report/', 'Omnisend (Ecommerce Marketing Report)', date '2026-01-01', true, '2025 activity across ~150,000 brands on Omnisend.'),
  ('More than 90% of shoppers say they are likely to abandon an online purchase if they learn shipping costs are high.', 'More than 90 percent', array['abandoned_cart_loss', 'unclear_value_prop'], array['online store', 'retail'], null, 'https://www.mckinsey.com/industries/logistics/our-insights/what-do-us-consumers-want-from-e-commerce-deliveries', 'McKinsey & Company', date '2025-01-01', false, '2024 survey of 1,000+ US consumers; stated intent.'),
  ('A product with five reviews is 270% more likely to be bought than one with no reviews.', '270%', array['no_proof'], array['online store', 'retail'], null, 'https://spiegel.medill.northwestern.edu/How-Online-Reviews-Influence-Sales', 'Spiegel Research Center, Northwestern University', date '2017-01-01', false, 'Retailers'' own sites, mostly CPG and gifts; gains flatten after about 5 reviews.'),
  ('72% of consumers say a product''s packaging design often influences what they buy.', '72%', array['weak_packaging'], array['online store', 'retail'], null, 'https://www.ipsos.com/en-us/news-polls/Most-Americans-Say-That-the-Design-of-a-Products-Packaging-Often-Influences-Their-Purchase-Decisions', 'Ipsos for the Paper and Packaging Board', date '2018-01-01', true, 'US survey sponsored by the paper-packaging industry.'),
  ('Email marketing returns about $36 for every $1 spent, the highest of any channel in Litmus''s research.', '$36', array['low_email_performance'], array[]::text[], 'GLOBAL', 'https://www.litmus.com/resources/email-marketing-roi', 'Litmus', date '2020-01-01', true, 'Self-reported marketer survey, about 2020; newer Litmus data gives ranges.'),
  ('Increasing customer retention by 5% increases profits by 25% to 95% (Bain & Company).', '25% to 95%', array['low_customer_retention'], array[]::text[], 'GLOBAL', 'https://www.bain.com/contentassets/29f74ec417fa4e36a1d7d7e7479badc5/loyalty_rules_chapter_one.pdf', 'Bain & Company (Frederick Reichheld)', date '2001-01-01', false, 'Landmark finding from industry case studies, not a universal rule; quote the range.'),
  ('Winning a new customer costs 5 to 25 times more than keeping an existing one, depending on the industry.', '5 to 25 times', array['low_customer_retention'], array[]::text[], 'GLOBAL', 'https://hbr.org/2014/10/the-value-of-keeping-the-right-customers', 'Harvard Business Review', date '2014-10-29', false, 'HBR cites it as a commonly reported range.'),
  ('Members of paid loyalty programs are 60% more likely to spend more with a brand after joining; free programs raise that likelihood by 30%.', '60%', array['low_customer_retention'], array['online store', 'retail', 'restaurant group', 'hotel chain'], null, 'https://www.mckinsey.com/capabilities/growth-marketing-and-sales/our-insights/coping-with-the-big-switch-how-paid-loyalty-programs-can-help-bring-consumers-back-to-your-brand', 'McKinsey & Company', date '2020-01-01', false, 'Survey of stated likelihood, not measured spend.'),
  ('31% of consumers will only use a local business rated 4.5 stars or higher, up from 17% a year earlier; 68% require at least 4 stars.', '31%', array['no_proof', 'competitor_pressure'], array['restaurant', 'restaurant group', 'spa', 'salón de belleza', 'estética', 'fitness studio', 'hotel', 'hotel chain', 'hospital', 'clínica'], null, 'https://www.brightlocal.com/research/local-consumer-review-survey/', 'BrightLocal (Local Consumer Review Survey 2026)', date '2026-01-01', true, 'Panel of 1,002 US adults.'),
  ('89% of consumers expect business owners to respond to online reviews.', '89%', array['no_proof', 'competitor_pressure', 'low_customer_retention'], array['restaurant', 'restaurant group', 'spa', 'salón de belleza', 'estética', 'fitness studio', 'hotel', 'hotel chain', 'hospital', 'clínica'], null, 'https://www.brightlocal.com/research/local-consumer-review-survey/', 'BrightLocal (Local Consumer Review Survey 2026)', date '2026-01-01', true, 'Panel of 1,002 US adults.'),
  ('85% of people say a brand''s video has convinced them to buy a product or service.', '85%', array['no_content_velocity', 'product_launch_support', 'poor_social_engagement'], array[]::text[], 'GLOBAL', 'https://wyzowl.com/video-marketing-statistics/', 'Wyzowl (State of Video Marketing 2026)', date '2026-01-01', true, 'Self-reported survey by a video production company.'),
  ('73% of social media users say they will buy from a competitor if a brand doesn''t respond to them on social.', '73%', array['poor_social_engagement', 'competitor_pressure'], array['restaurant', 'restaurant group', 'spa', 'salón de belleza', 'estética', 'fitness studio', 'hotel', 'hotel chain', 'online store', 'retail'], null, 'https://sproutsocial.com/insights/social-media-statistics/', 'Sprout Social (Sprout Social Index)', date '2025-01-01', true, 'Vendor survey; geography and sample not confirmed.'),
  ('Independent hotels can pay OTA commissions as high as 30% of room revenue, while large chains negotiate them down to about 15%.', '30%', array['outdated_website', 'competitor_pressure', 'low_customer_retention'], array['hotel', 'hotel chain'], 'GLOBAL', 'https://www.hospitalitynet.org/file/152005663.pdf', 'HVS London (via Hospitality Net)', null, false, 'Publication year not shown (about mid-2010s); the paper says big OTAs typically charge 20-25%. Booking.com''s rate varies by country.'),
  ('In the US, online travel agencies take 52% of online hotel bookings versus 48% for hotels'' own websites and apps.', '52%', array['outdated_website', 'competitor_pressure'], array['hotel', 'hotel chain'], null, 'https://www.phocuswire.com/news/online/us-hotel-lodging-travel-market-essentials-phocuswright-research-2026', 'Phocuswright (via PhocusWire)', date '2026-01-01', false, 'US online bookings only.'),
  ('For independent hotels, OTA bookings are cancelled about twice as often as direct bookings (21.8% vs 10.6%), and OTAs supply 63.4% of their bookings.', '21.8%', array['outdated_website', 'low_customer_retention', 'competitor_pressure'], array['hotel'], 'GLOBAL', 'https://hotelbusiness.com/cloudbeds-report-otas-dominate-independent-hotel-bookings/', 'Cloudbeds State of Independent Hotels 2026 (via Hotel Business)', date '2026-01-01', true, 'Hotel software vendor data (90M bookings, 180 countries); independent hotels only.')
) as v(statistic, figure, pain_codes, industry_scope, market, source_url, publisher, published_date, is_vendor_sourced, caveat)
where not exists (
  select 1 from public.benchmarks b
  where b.tenant_id = t.id and b.source_url = v.source_url and b.figure = v.figure
);
